# 1. prompted value: how many times do type.convert and callback run?
calls = []
class T(click.ParamType):
    name = "t"
    def convert(self, v, p, c):
        calls.append(("convert", repr(v))); return int(v)
def cb(ctx, p, v):
    calls.append(("callback", v)); return v
@click.command()
@click.option("--n", type=T(), prompt=True, callback=cb)
def c1(n): print("got", n)
print(r.invoke(c1, [], input="7\n").output.strip()); print(calls)

# 2. same with value from the command line
calls.clear(); print(r.invoke(c1, ["--n", "7"]).output.strip()); print(calls)

